// A crystal: an uneven prism with a pointed tip, all flat facets.
// Units: mm.

const n_tau = PI * 2;
const n_height = 130;
// 120 layers puts every height in a_o_key below exactly on a
// layer, so the edges between the facets stay sharp.
const n_its_layer = 120;
// Few corners make big facets. 6 looks like quartz; 5 or 7 look
// less regular.
const n_its_corner = 7;
const n_height_cone = 12;
// No dome: the crystal ends in a point on its own.
const n_height_dome = 0;
const n_overhang_dome = 60;

// Another seed gives another crystal, from 1 to 65535.
noise.seed(11);

// The outline from bottom to tip: [height from 0 to 1, radius in mm].
// Between two of these the walls are straight, which makes flat
// facets. Keep the heights at multiples of 1/40 (0.025) so they
// fall on layers.
const a_o_key = [
    [0.000, 38],
    [0.250, 46],
    [0.500, 44],
    [0.650, 40],   // the shoulder, where the point starts
    [0.850, 18],
    [1.000, 1.5],  // the tip
];
// How unevenly each facet is cut, in mm. It shrinks toward the tip.
const n_jitter_radius = 5;
// How unevenly the corners are spaced around, as a share of the
// space between two corners.
const n_jitter_angle = 0.3;
// The tip is this far off the axis, so it leans a little.
const n_tip_x = 5;
const n_tip_y = -3;
const n_shoulder = 0.65;

// A fixed random number from -1 to 1 for each corner and height.
function f_n_rand(n_a, n_b) {
    return noise.simplex2(n_a * 3.17 + 0.5, n_b * 2.31 + 0.5);
}

function f_o_p(n_it_layer_nor, n_it_corner_nor) {
    const n_t = n_it_layer_nor;
    const i_corner = round(n_it_corner_nor * n_its_corner)
        % n_its_corner;

    // Which two heights in a_o_key this layer lies between.
    let i_key = 0;
    while (i_key < a_o_key.length - 2 && n_t > a_o_key[i_key + 1][0]) {
        i_key++;
    }
    const o_k0 = a_o_key[i_key];
    const o_k1 = a_o_key[i_key + 1];
    const n_u = clamp((n_t - o_k0[0]) / (o_k1[0] - o_k0[0]), 0, 1);

    // The random offset at each of those two heights. It shrinks
    // with the radius, so the tip stays a clean point.
    const n_j0 = f_n_rand(i_corner, i_key) * n_jitter_radius
        * o_k0[1] / 46;
    const n_j1 = f_n_rand(i_corner, i_key + 1) * n_jitter_radius
        * o_k1[1] / 46;

    // A straight line between them makes a flat facet.
    const n_r = mix(o_k0[1] + n_j0, o_k1[1] + n_j1, n_u);

    // The corners are spaced unevenly, the same way all the way up.
    const n_angle = (i_corner
        + f_n_rand(i_corner, 17) * n_jitter_angle)
        / n_its_corner * n_tau;

    // Above the shoulder, move toward the off-axis tip in a straight line.
    const n_lean = clamp((n_t - n_shoulder) / (1 - n_shoulder), 0, 1);

    return {
        n_x: sin(n_angle) * n_r + n_tip_x * n_lean,
        n_y: cos(n_angle) * n_r + n_tip_y * n_lean,
        n_z: o_thread.n_z + n_height_cone + n_t * n_height,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p,
};
